import{_ as e}from"./chunks/01-editor-overview.B6DfPzWc.js";import{_ as r,a as o,b as n,c as s,d as a,e as i,f as d,g}from"./chunks/12-editor-render.C4Mg-YM8.js";import{_ as l,o as h,c,a2 as p}from"./chunks/framework.BM5YPQmL.js";const C=JSON.parse('{"title":"The editor","description":"","frontmatter":{},"headers":[],"relativePath":"guide/editor.md","filePath":"guide/editor.md"}'),m={name:"guide/editor.md"};function u(f,t,y,w,v,b){return h(),c("div",null,[...t[0]||(t[0]=[p('<h1 id="the-editor" tabindex="-1">The editor <a class="header-anchor" href="#the-editor" aria-label="Permalink to &quot;The editor&quot;">​</a></h1><p>The editor is where you design an episode. It works like a design tool on top of a video timeline, but it is made for one job. You place animated components on the real 1080×1920 frame and time them to the words you speak.</p><p>Open it from the dashboard with <strong>Open editor</strong>, or run <code>reelforge edit &lt;id&gt;</code>. <code>reelforge cue &lt;id&gt;</code> opens it in Cues mode and <code>reelforge dev &lt;id&gt;</code> in Review mode.</p><p><img src="'+e+'" alt="The editor"></p><table tabindex="0"><thead><tr><th>Area</th><th>What it holds</th></tr></thead><tbody><tr><td><strong>Top bar</strong></td><td>Modes (Edit · Cues · Review), undo/redo, transport and speed, status, checks, search, <strong>Render</strong></td></tr><tr><td><strong>Left panel</strong></td><td><strong>Layers</strong> (scenes → elements), <strong>Insert</strong> (every component) and <strong>Script</strong> (your lines)</td></tr><tr><td><strong>Canvas</strong></td><td>The real frame, rendered by the same engine as the final video, synced to your voice</td></tr><tr><td><strong>Right panel</strong></td><td>The <strong>Inspector</strong> for whatever is selected (or the episode settings when nothing is)</td></tr><tr><td><strong>Timeline</strong></td><td>Chapters, scenes, script lines, one track per layer, and your voice waveform with sound effects</td></tr></tbody></table><p>Every change is written to <code>episode.yaml</code> immediately, and your comments and formatting are kept. Every change can also be undone (<strong>⌘Z</strong> / <strong>Ctrl+Z</strong>), including cue changes. You can keep <code>episode.yaml</code> open in a text editor at the same time. Edits made there appear in the editor as soon as you save.</p><h2 id="canvas" tabindex="-1">Canvas <a class="header-anchor" href="#canvas" aria-label="Permalink to &quot;Canvas&quot;">​</a></h2><ul><li><strong>Click</strong> an element to select it. <strong>Alt+click</strong> selects the one underneath. Hover shows an outline.</li><li><strong>Drag</strong> to move. Smart guides snap to the frame center, the scene area and other elements. Hold <strong>Shift</strong> to move in a straight line, or <strong>Alt</strong> to turn snapping off.</li><li><strong>Drag a handle</strong> to resize. Hold <strong>Shift</strong> to keep the proportions, or <strong>Alt</strong> to resize from the center.</li><li>Use the <strong>arrow keys</strong> to nudge 1 px (<strong>Shift</strong>: 10 px).</li><li><strong>Double-click</strong> a title, label, chip, stamp, quote, node or ending card to <strong>edit its text in place</strong>. Press <strong>Enter</strong> to save or <strong>Esc</strong> to cancel.</li><li><strong>Drag a component</strong> from <strong>Insert</strong> onto the canvas to add it there.</li><li><strong>Zoom</strong> with <strong>⌘/Ctrl + wheel</strong>, <strong>Shift+1</strong> (fit), <strong>Shift+2</strong> (selection) or <strong>Shift+0</strong> (100%). <strong>Pan</strong> with the wheel, by holding <strong>Space</strong>, or with the <strong>H</strong> tool.</li><li>The floating toolbar toggles the <strong>safe zones</strong> (<strong>Z</strong>, where TikTok/Reels/Shorts draw their buttons), <strong>stage and caption guides</strong> (<strong>B</strong>) and <strong>element outlines</strong> (<strong>E</strong>).</li></ul><p><img src="'+r+'" alt="Moving with smart guides"></p><h2 id="layers-insert-and-script" tabindex="-1">Layers, Insert and Script <a class="header-anchor" href="#layers-insert-and-script" aria-label="Permalink to &quot;Layers, Insert and Script&quot;">​</a></h2><p><strong>Layers</strong> lists every scene and its elements. The top of each list is drawn on top. Click to select (the playhead jumps to a moment when the element is visible), <strong>drag</strong> to reorder, and <strong>double-click</strong> to rename. Renaming also updates any arrows that point at the element. A green dot marks what is on screen at the playhead.</p><p><strong>Insert</strong> shows all 62 components in groups: Text, Diagrams, Data, Charts, Process &amp; structure, Places &amp; movement, Time, People &amp; messaging, Media &amp; text, Health &amp; data, Code &amp; devices, Effects &amp; endings. <strong>Click</strong> one to add it to the current scene at the playhead, or drag it onto the canvas. New elements start with sensible content that you can change at once.</p><p><img src="'+o+'" alt="Insert panel"></p><p><strong>Script</strong> is your text, one spoken sentence per line. Edit a line in place. Use the line&#39;s buttons to add, delete or reorder lines. Arabic, English and mixed lines are all supported, and the direction is detected automatically.</p><h2 id="inspector" tabindex="-1">Inspector <a class="header-anchor" href="#inspector" aria-label="Permalink to &quot;Inspector&quot;">​</a></h2><p>The inspector edits <strong>every property</strong> of the selection:</p><ul><li><strong>Position &amp; size</strong> (X, Y, W, H), alignment buttons, layer and stacking order.</li><li><strong>Animation &amp; timing</strong>: when it enters, the animation, its ease and duration, and an optional exit. <strong>Preview animation</strong> plays just that moment once; choosing a new animation or ease previews it automatically. The <strong>target</strong> button sets a time from the playhead. It writes a word-anchored time such as <code>l3:&#39;bucket&#39;</code> whenever the playhead is on a word, so the element stays on that word even after you re-record.</li><li><strong>Properties</strong>: every option of the component, generated from its schema. That covers text fields, numbers (drag the dotted handle to scrub), on/off switches, menus, colors (theme swatches or any color), times, and lists you can add to, reorder and remove from.</li><li><strong>Effects</strong> (shake, flash, glitch, pulse, bump) and <strong>States</strong> (prop changes at a time, e.g. a node turning red).</li><li><strong>Sound</strong>: automatic sound effects on or off.</li><li><strong>YAML (advanced)</strong>: the exact YAML of the element. Anything the format supports can be edited here.</li></ul><p>With a <strong>scene</strong> selected, the inspector edits its start and end, transition, camera move (with <strong>Preview transition</strong>), area (stage or full frame), background glow and auto-layout. With a <strong>script line</strong> selected, it edits the text, caption, line breaks and cue, and lists every word (click one to jump to it). With <strong>nothing</strong> selected, it edits the episode: title, series, platform, theme, language, publishing texts, audio and chapters.</p><p><img src="'+n+'" alt="Script line in the inspector"></p><h2 id="timeline" tabindex="-1">Timeline <a class="header-anchor" href="#timeline" aria-label="Permalink to &quot;Timeline&quot;">​</a></h2><p><img src="'+s+'" alt="Retiming a clip on the timeline"></p><ul><li><strong>Click or drag the ruler</strong> to move the playhead. Chapters are shown on the ruler.</li><li><strong>Scenes</strong>: drag a scene&#39;s start to move it.</li><li><strong>Script</strong>: each line is a clip. Drag it to change its cue. Its word marks move with it.</li><li><strong>Layer tracks</strong>: each element is a clip from when it enters to when it leaves. <ul><li>Drag the <strong>body</strong> to retime it.</li><li>Drag the <strong>left edge</strong> to change when it enters.</li><li>Drag the <strong>right edge</strong> to set when it leaves. Dragging it to the end of the scene removes the exit.</li><li>Diamonds mark effects (orange) and state changes (blue).</li></ul></li><li>Clips snap to <strong>words</strong>, line starts, scenes and the playhead. The badge shows the time expression that will be saved. Hold <strong>Alt</strong> to drag freely, or press <strong>S</strong> to turn snapping off.</li><li><strong>I</strong> and <strong>O</strong> set the selected element&#39;s in and out points at the playhead.</li><li><strong>Zoom</strong> with <strong>= / −</strong>, the slider or <strong>⌘/Ctrl + wheel</strong>. <strong>\\</strong> fits the whole episode.</li></ul><h2 id="search-everything-⌘k-ctrl-k" tabindex="-1">Search everything: ⌘K / Ctrl+K <a class="header-anchor" href="#search-everything-⌘k-ctrl-k" aria-label="Permalink to &quot;Search everything: ⌘K / Ctrl+K&quot;">​</a></h2><p>The command palette finds every command, component, scene, element and script line. Type a few letters and press <strong>Enter</strong>. Try <code>insert counter</code>, <code>go to scene trap</code> or <code>safe zones</code>.</p><p><img src="'+a+'" alt="Command palette"></p><p>Right-click the canvas, a layer or a clip for the most common actions. Press <strong>?</strong> to see every shortcut.</p><p><img src="'+i+'" alt="Keyboard shortcuts"></p><h2 id="review-mode" tabindex="-1">Review mode <a class="header-anchor" href="#review-mode" aria-label="Permalink to &quot;Review mode&quot;">​</a></h2><p><strong>Review</strong> (<strong>Alt+3</strong>, or click the checks pill in the top bar) lists every issue found by the checks: schema, timing, overlaps, safe zones, text overflow measured in the real browser, and caption length. Each issue has a fix hint. Click an issue to jump to its time and select the element.</p><p><img src="'+d+'" alt="Review mode"></p><p>If <code>episode.yaml</code> has a syntax error (for example after editing it by hand), a banner shows the line and the message. The editor keeps showing the last version that worked.</p><h2 id="rendering-from-the-editor" tabindex="-1">Rendering from the editor <a class="header-anchor" href="#rendering-from-the-editor" aria-label="Permalink to &quot;Rendering from the editor&quot;">​</a></h2><p>Click <strong>Render</strong> (<strong>⌘/Ctrl+Enter</strong>) and choose the platform, the share-file size, sound effects, silent mode (when there is no recording yet) and a fast draft. You can keep editing while it renders, and the progress shows in the top bar. When it finishes, the videos open in a player with download links.</p><p><img src="'+g+'" alt="Render"></p><h2 id="shortcuts-at-a-glance" tabindex="-1">Shortcuts at a glance <a class="header-anchor" href="#shortcuts-at-a-glance" aria-label="Permalink to &quot;Shortcuts at a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Keys</th><th>Action</th></tr></thead><tbody><tr><td><strong>Space</strong> / <strong>K</strong></td><td>Play / pause</td></tr><tr><td><strong>J</strong> / <strong>L</strong>, <strong>,</strong> / <strong>.</strong></td><td>−1 s / +1 s, previous / next frame</td></tr><tr><td><strong>Home</strong> / <strong>End</strong></td><td>Start / end</td></tr><tr><td><strong>1 2 3</strong></td><td>Speed 0.5× 0.75× 1×</td></tr><tr><td><strong>⌘/Ctrl+Z</strong>, <strong>⌘/Ctrl+Shift+Z</strong></td><td>Undo, redo</td></tr><tr><td><strong>⌘/Ctrl+D</strong>, <strong>⌘/Ctrl+C</strong>, <strong>⌘/Ctrl+V</strong></td><td>Duplicate, copy, paste at the playhead</td></tr><tr><td><strong>Delete</strong></td><td>Delete the selection</td></tr><tr><td><strong>⌘/Ctrl+]</strong>, <strong>⌘/Ctrl+[</strong></td><td>Bring forward, send backward</td></tr><tr><td><strong>I</strong> / <strong>O</strong></td><td>Enter / exit at the playhead</td></tr><tr><td><strong>A</strong></td><td>Insert a component</td></tr><tr><td><strong>N</strong></td><td>Add a scene at the playhead</td></tr><tr><td><strong>Tab</strong> / <strong>Shift+Tab</strong></td><td>Next / previous element</td></tr><tr><td><strong>Z</strong>, <strong>B</strong>, <strong>E</strong></td><td>Safe zones, stage guides, outlines</td></tr><tr><td><strong>S</strong></td><td>Snapping</td></tr><tr><td><strong>Alt+1 / 2 / 3</strong></td><td>Edit / Cues / Review</td></tr><tr><td><strong>⌘/Ctrl+K</strong></td><td>Command palette</td></tr><tr><td><strong>?</strong></td><td>All shortcuts</td></tr></tbody></table>',36)])])}const S=l(m,[["render",u]]);export{C as __pageData,S as default};
